		require(checksum == seed.checksum(), "Batch checksum differs from the independent seed oracle");
		return new Batch(observed, checksum, context.sourceCalls - beforeCalls, context.coldCompletions - beforeCold,
				samePrevious, sameOriginal, clearedAtLookup, coldAtLookup);
