	private static void allocatePressure(int round) {
		for (int index = 0; index < PRESSURE_BYTES / ARRAY_BYTES; index++) {
			byte[] allocation = new byte[ARRAY_BYTES];
			for (int page = 0; page < allocation.length; page += 4096) {
				allocation[page] = (byte) (round + index);
			}
			pressureSink = allocation;
		}
		pressureSink = null;
	}

	private static WeakReference<Object> collectionControl() {
		return new WeakReference<>(new Object());
	}

	private static int clearedMask(Observed[] observed, boolean payload) {
		int mask = 0;
		for (int index = 0; index < observed.length; index++) {
			WeakReference<?> reference = payload ? observed[index].payload() : observed[index].value();
			if (reference.refersTo(null)) {
				mask |= 1 << index;
			}
		}
		return mask;
	}

	private static long verifyPayload(String text, int serial, int characters) {
		String prefix = prefix(serial);
		require(text.length() == characters && text.startsWith(prefix), "Incorrect IRI prefix or length");
		char padding = padding(serial);
		long hash = HASH_SEED;
		for (int index = 0; index < text.length(); index++) {
			char current = text.charAt(index);
			require(index < prefix.length() || current == padding, "Incorrect IRI payload character");
			hash = (hash ^ current) * HASH_MULTIPLIER;
		}
		return hash;
	}

	private static long fold(long previous, long id, long lexicalHash) {
		return ((previous ^ id) * HASH_MULTIPLIER ^ lexicalHash) * HASH_MULTIPLIER;
	}

	private static String prefix(int serial) {
		return "urn:natural-gc-memo:" + serial + ':';
	}

	private static char padding(int serial) {
		return (char) ('a' + serial % 26);
	}

	private static GcSnapshot gcSnapshot() {
		long count = 0L;
		long millis = 0L;
		for (GarbageCollectorMXBean collector : ManagementFactory.getGarbageCollectorMXBeans()) {
			count += Math.max(0L, collector.getCollectionCount());
			millis += Math.max(0L, collector.getCollectionTime());
		}
		return new GcSnapshot(count, millis);
	}

