		number(json, "native_map_bytes", config().getValueDBSize());
		number(json, "default_source_value_cache_size", config().getValueCacheSize());
		number(json, "default_source_value_id_cache_size", config().getValueIDCacheSize());
		number(json, "keys", KEYS);
		number(json, "characters_per_key", seed.characters());
