	private static final class Consumer {
		LmdbValue value;
	}

	private static final class Context implements AutoCloseable {
		final ValueStore store;
		final LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(BUDGET, BUDGET);
		final LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
		final NativeDirectValueMemo memo;
		long sourceCalls;
		long sourceReturnedCold;
		long sourceReturnedInitialized;
		long coldCompletions;
		long samePreviousReturns;
		long samePreviousSourceReturns;

		Context(ValueStore store, boolean enabled) {
			this.store = store;
			memo = enabled ? new NativeDirectValueMemo(ledger) : null;
		}

		@Override
		public void close() {
			try {
				if (memo != null) {
					memo.close();
				}
			} finally {
				ledger.close();
			}
		}
	}
